update public.learning_paths
set
  title = 'Architectural History III (Non-Western / Contemporary)',
  goal = 'Architectural History III (Non-Western / Contemporary)',
  summary = 'Architectural History III studies architecture as a global, non-Western, contemporary, and decolonial history in which Euro-American canons are no longer the default center. Students build tools for historiography, archives, fieldwork, and visual analysis, then examine Indigenous and climate-responsive environments, Islamic, South and Southeast Asian, East Asian, African, and Latin American and Caribbean traditions, colonialism and national identity, regional modernisms, housing and everyday urbanism, global cities, digital practice, climate and environmental justice, contemporary Global South practices, heritage politics, and identity in public space. A capstone compares buildings, cities, or practices through images, maps, drawings, and scholarly argument.',
